import numpy as np

def letter_means(letters, count=5, low=0, high=10, seed=None):
    """
    Create a dict mapping each letter in `letters` to a list of `count` random integers in [low, high),
    then return a dict mapping each letter to the mean of its integers.
    """
    if seed is not None:
        np.random.seed(seed)
    data = {ch: np.random.randint(low, high, size=count).tolist() for ch in letters}
    means = {ch: float(np.mean(vals)) for ch, vals in data.items()}
    return means

# Example:
