def closest_to_threshold(list1, list2, threshold=0.0):
    """
    Alternate elements from list1 and list2 into a single sequence,
    compute absolute differences from `threshold`, and return the element
    closest to the threshold. If lists are of unequal length, remaining
    elements are appended in order. Raises ValueError if both lists are empty.
    """
    import numpy as np

    if not list1 and not list2:
        raise ValueError("Both input lists are empty.")

    merged = []
    m = max(len(list1), len(list2))
    for i in range(m):
        if i < len(list1):
            merged.append(list1[i])
        if i < len(list2):
            merged.append(list2[i])

    arr = np.asarray(merged, dtype=float)
    idx = int(np.abs(arr - threshold).argmin())
    return arr[idx].item()

import numpy as np

def closest_alternate(list1, list2, threshold=0):
    """
    Alternate elements from two numeric lists, compute absolute differences from threshold,
    and return the element closest to the threshold (first in case of tie).
    Raises ValueError if both lists are empty.
    """
    res = []
    n = max(len(list1), len(list2))
    for i in range(n):
        if i < len(list1):
            res.append(list1[i])
        if i < len(list2):
            res.append(list2[i])
    if not res:
        raise ValueError("Both input lists are empty")
    arr = np.array(res, dtype=float)
    return arr[np.argmin(np.abs(arr - threshold))].item()

