def resolve_and_geolocate(host, timeout=5):
    """
    Resolve the IP address for `host` and fetch geolocation from ipinfo.io.
    Returns a dict: {
        "success": bool,
        "ip": str or None,
        "geo": dict or None,
        "note": str or None,   # e.g. "private", "loopback"
        "error": str or None
    }
    The function is robust to invalid hostnames, network errors, bad JSON, etc.
    Requires the `requests` library.
    """
    try:
        import socket, urllib.parse, ipaddress, requests
    except Exception as e:
        return {"success": False, "ip": None, "geo": None, "note": None, "error": f"Missing import: {e}"}

    if not host:
        return {"success": False, "ip": None, "geo": None, "note": None, "error": "No host provided"}

    # If a URL is passed, extract the hostname
    try:
        parsed = urllib.parse.urlparse(host)
        hostname = parsed.hostname if parsed.scheme and parsed.hostname else host
    except Exception:
        hostname = host

    # Strip common [ipv6]:port or host:port forms
    if hostname.startswith('[') and hostname.endswith(']'):
        hostname = hostname[1:-1]
    if ':' in hostname and not hostname.count(':') > 1:  # likely host:port for IPv4 or name:port
        parts = hostname.rsplit(':', 1)
        if parts[1].isdigit():
            hostname = parts[0]

    # Resolve DNS (works for hostnames or IPs)
    try:
        addrinfo = socket.getaddrinfo(hostname, None)
        if not addrinfo:
            return {"success": False, "ip": None, "geo": None, "note": None, "error": "No address info returned"}
        ip = addrinfo[0][4][0]
    except socket.gaierror as e:
        return {"success": False, "ip": None, "geo": None, "note": None, "error": f"DNS resolution failed: {e}"}
    except Exception as e:
        return {"success": False, "ip": None, "geo": None, "note": None, "error": f"Unexpected resolution error: {e}"}

    note = None
    try:
        ip_obj = ipaddress.ip_address(ip)
        if ip_obj.is_loopback:
            note = "loopback"
        elif ip_obj.is_private:
            note = "private"
        elif ip_obj.is_reserved:
            note = "reserved"
    except Exception:
        # if ip parsing fails, continue — we'll still try ipinfo
        pass

    # Query ipinfo.io
    url = f"https://ipinfo.io/{ip}/json"
    try:
        resp = requests.get(url, timeout=timeout)
        resp.raise_for_status()
        data = resp.json()
    except requests.exceptions.RequestException as e:
        return {"success": False, "ip": ip, "geo": None, "note": note, "error": f"Network/service error: {e}"}
    except ValueError as e:
        return {"success": False, "ip": ip, "geo": None, "note": note, "error": f"Invalid JSON from service: {e}"}

    return {"success": True, "ip": ip, "geo": data, "note": note, "error": None}

