def veg_stats(people_to_veg, seed=None):
    """
    Given a dict mapping people -> vegetable, returns statistics about vegetables.
    - Reverses to veg -> list_of_people
    - Picks one person per vegetable (randomly) to create veg -> person map
    - Assigns a random count (1-10) to each vegetable
    - Calculates each vegetable's percentage of the total counts using pandas

    Returns a dict with keys:
      'veg_to_people', 'veg_to_person', 'counts', 'percentages', 'total_count'
    """
    import random
    import pandas as pd

    if seed is not None:
        random.seed(seed)

    # reverse mapping: vegetable -> list of people who prefer it
    veg_to_people = {}
    for person, veg in (people_to_veg or {}).items():
        veg_to_people.setdefault(veg, []).append(person)

    # map each vegetable to one person (random choice among those who had it)
    veg_to_person = {veg: random.choice(people) for veg, people in veg_to_people.items()}

    # assign random counts between 1 and 10 to each vegetable
    counts = {veg: random.randint(1, 10) for veg in veg_to_people.keys()}

    # use pandas to compute percentages
    s = pd.Series(counts, dtype=int)
    total = int(s.sum()) if not s.empty else 0
    if total > 0:
        percentages = (s / total * 100).round(2).to_dict()
    else:
        percentages = {veg: 0.0 for veg in counts.keys()}

    return {
        'veg_to_people': veg_to_people,
        'veg_to_person': veg_to_person,
        'counts': counts,
        'percentages': percentages,
        'total_count': total
    }

