def most_common_words_in_json_dir(directory, top_n=10):
    """
    Read all .json files in `directory`, extract text content, and return the top_n most common words.
    Returns a list of (word, count) tuples sorted by descending frequency.
    """
    import os, json, re
    import pandas as pd

    if not os.path.isdir(directory):
        raise ValueError(f"Directory not found: {directory}")

    words = []
    for fname in os.listdir(directory):
        if not fname.lower().endswith('.json'):
            continue
        path = os.path.join(directory, fname)
        try:
            with open(path, 'r', encoding='utf-8') as f:
                obj = json.load(f)
        except Exception:
            # skip files that can't be read/parsed
            continue

        # Convert JSON content to a single text string.
        if isinstance(obj, str):
            text = obj
        else:
            try:
                df = pd.json_normalize(obj)
                if df.empty:
                    text = str(obj)
                else:
                    # join all cells (rows) into one big string
                    text = ' '.join(df.astype(str).agg(' '.join, axis=1).tolist())
            except Exception:
                text = str(obj)

        # extract words (lowercased). Pattern keeps letters and apostrophes.
        words.extend(re.findall(r"[a-z']+", text.lower()))

    if not words:
        return []

    counts = pd.Series(words).value_counts().head(top_n)
    return list(counts.items())

