def mean_per_position(data, json_path=None):
    """
    Compute the mean of numeric values for each index/position across the provided data list.
    Non-numeric values, missing entries, and non-finite numbers (NaN/Inf) are ignored.
    Returns a list of means (float) or None for positions with no numeric values.
    If json_path is provided, the results are also written to that JSON file.
    """
    import numpy as np
    import json

    data = list(data)  # allow any iterable
    if not data:
        if json_path:
            with open(json_path, "w") as f:
                json.dump([], f)
        return []

    # determine maximum row length (skip items that aren't sized)
    maxlen = 0
    for row in data:
        try:
            l = len(row)
        except Exception:
            continue
        if l > maxlen:
            maxlen = l

    results = []
    for i in range(maxlen):
        vals = []
        for row in data:
            try:
                v = row[i]
            except Exception:
                continue
            try:
                fv = float(v)
            except Exception:
                continue
            if np.isfinite(fv):
                vals.append(fv)
        results.append(float(np.mean(vals)) if vals else None)

    if json_path:
        with open(json_path, "w") as f:
            json.dump(results, f)

    return results
