def protect_quotes_in_dir(directory):
    """
    Protect all double quotes in all .xlsx files in the given directory by
    prefixing them with a double backslash (i.e. replace " with \\").
    Uses openpyxl. Modifies files in place and returns a list of modified file paths.
    """
    import os
    import glob
    from openpyxl import load_workbook
    from openpyxl.comments import Comment

    replaced = '\\\\' + '"'  # two backslashes + a double-quote character
    modified_files = []

    pattern = os.path.join(directory, '*.xlsx')
    for path in glob.glob(pattern):
        # skip temporary Excel files
        if os.path.basename(path).startswith('~$'):
            continue

        try:
            wb = load_workbook(path)
        except Exception:
            # skip files that can't be opened
            continue

        changed = False

        for sheet in wb.worksheets:
            # Protect quotes in sheet title
            if '"' in sheet.title:
                try:
                    sheet.title = sheet.title.replace('"', replaced)
                    changed = True
                except Exception:
                    # invalid/duplicate title after change -> skip changing title
                    pass

            # Protect quotes in cell values and comments
            for row in sheet.iter_rows():
                for cell in row:
                    val = cell.value
                    if isinstance(val, str):
                        # skip formulas (they start with '='), to avoid breaking them
                        if not val.startswith('=') and '"' in val:
                            cell.value = val.replace('"', replaced)
                            changed = True

                    # comments (if present)
                    c = cell.comment
                    if c is not None and isinstance(c.text, str) and '"' in c.text:
                        new_text = c.text.replace('"', replaced)
                        # recreate the Comment with same author
                        cell.comment = Comment(new_text, c.author)
                        changed = True

        if changed:
            try:
                wb.save(path)
                modified_files.append(path)
            except Exception:
                # if save fails, ignore and continue
                pass

    return modified_files

