import os
from openpyxl import load_workbook

def protect_quotes_in_dir(dir_path):
    """
    For every .xlsx file in dir_path, prefix every double-quote character (")
    in plain text cell values with a double backslash (\\").
    Formula cells (values starting with '=') are not modified.
    Files are overwritten in place.
    """
    if not os.path.isdir(dir_path):
        raise ValueError(f"Not a directory: {dir_path}")

    for name in os.listdir(dir_path):
        if not name.lower().endswith('.xlsx'):
            continue
        if name.startswith('~$'):  # skip Excel temp files
            continue

        path = os.path.join(dir_path, name)
        try:
            wb = load_workbook(path)
        except Exception as e:
            print(f"Skipping {path}: cannot open workbook ({e})")
            continue

        changed = False
        for ws in wb.worksheets:
            for row in ws.iter_rows():
                for cell in row:
                    v = cell.value
                    if isinstance(v, str) and '"' in v and not v.startswith('='):
                        cell.value = v.replace('"', '\\\\\"')
                        changed = True

        if changed:
            try:
                wb.save(path)
                print(f"Updated: {path}")
            except Exception as e:
                print(f"Failed to save {path}: {e}")
        else:
            wb.close()
