import pandas as pd
from sklearn.model_selection import train_test_split

def split_data(df: pd.DataFrame, target_col: str, drop_col: str = None,
               test_size: float = 0.25, random_state: int = None):
    """
    Split df into train/test after removing drop_col if it exists.
    Returns: X_train, X_test, y_train, y_test
    """
    if target_col not in df.columns:
        raise ValueError(f"target_col '{target_col}' not found in dataframe")
    if drop_col is not None:
        if drop_col == target_col:
            raise ValueError("drop_col is the same as target_col; cannot drop the target column")
        if drop_col in df.columns:
            df = df.drop(columns=[drop_col])
    X = df.drop(columns=[target_col])
    y = df[target_col]
    return train_test_split(X, y, test_size=test_size, random_state=random_state)

def json_to_xls(json_str, filename):
    """
    Convert a JSON string to an Excel .xls file using xlwt.
    - json_str: JSON string representing an object, an array, or a primitive.
    - filename: target filename for the .xls file (e.g. 'out.xls').
    If json_str is "[]", an Excel file with an empty sheet (no data rows) is created.
    """
    import json
    import xlwt

    try:
        data = json.loads(json_str)
    except Exception as e:
        raise ValueError("Invalid JSON") from e

    wb = xlwt.Workbook()
    ws = wb.add_sheet('Sheet1')

    # If it's an empty array, create sheet with no data rows and save
    if isinstance(data, list) and len(data) == 0:
        wb.save(filename)
        return

    # Helper to stringify values for writing
    def _fmt(v):
        return "" if v is None else str(v)

    # List handling
    if isinstance(data, list):
        first = data[0]
        # If it's a list of dicts, build a header from keys (including keys that appear later)
        if isinstance(first, dict):
            keys = list(first.keys())
            for item in data[1:]:
                if isinstance(item, dict):
                    for k in item.keys():
                        if k not in keys:
                            keys.append(k)
            # header
            for c, k in enumerate(keys):
                ws.write(0, c, k)
            # rows
            for r, item in enumerate(data, start=1):
                if isinstance(item, dict):
                    for c, k in enumerate(keys):
                        ws.write(r, c, _fmt(item.get(k)))
                else:
                    ws.write(r, 0, _fmt(item))
        else:
            # list of primitives (or lists) -> one column per item
            for r, item in enumerate(data):
                ws.write(r, 0, _fmt(item))

    # Single dict -> header row + one data row
    elif isinstance(data, dict):
        keys = list(data.keys())
        for c, k in enumerate(keys):
            ws.write(0, c, k)
            ws.write(1, c, _fmt(data.get(k)))

    # Primitive -> single cell
    else:
        ws.write(0, 0, _fmt(data))

    wb.save(filename)

