```python
import json
import xlwt

def json_to_excel(json_str, filename):
    """
    Convert a JSON string to an Excel .xls file using xlwt.
    - If the JSON is an array of objects, writes headers and rows.
    - If the JSON is an empty array ([]), creates a workbook with an empty sheet (no data rows).
    - If the JSON is a single object (dict), writes one row.
    - For non-object values, writes the value into cell A1.
    """
    data = json.loads(json_str)
    wb = xlwt.Workbook()
    ws = wb.add_sheet("Sheet1")

    # Handle list (array)
    if isinstance(data, list):
        if len(data) == 0:
            # Empty array -> create file with empty sheet (no data rows)
            wb.save(filename)
            return
        # Collect headers in order of first occurrence across objects
        headers = []
        for item in data:
            if isinstance(item, dict):
                for k in item.keys():
                    if k not in headers:
                        headers.append(k)
            else:
                # If array contains non-dict items, treat each as a single-column value
                headers = ["value"]
                break

        # Write headers
        for c, h in enumerate(headers):
            ws.write(0, c, h)

        # Write rows
        for r, item in enumerate(data, start=1):
            if isinstance(item, dict):
                for c, h in enumerate(headers):
                    v = item.get(h, "")
                    if v is None:
                        v = ""
                    elif isinstance(v, (dict, list)):
                        v = json.dumps(v, ensure_ascii=False)
                    ws.write(r, c, v)
            else:
                # non-dict items -> put in first column
                v = item
                if v is None:
                    v = ""
                elif isinstance(v, (dict, list)):
                    v = json.dumps(v, ensure_ascii=False)
                ws.write(r, 0, v)

    # Handle single object (dict)
    elif isinstance(data, dict):
        headers = list(data.keys())
        for c, h in enumerate(headers):
            ws.write(0, c, h)
            v = data[h]
            if v is None:
                v = ""
            elif isinstance(v, (dict, list)):
                v = json.dumps(v, ensure_ascii=False)
            ws.write(1, c, v)

    # Handle primitive (string, number, etc.)
    else:
        v = data
