def task_func(MIN_WORDS, MAX_WORDS, WORDS_POOL):
    import numpy as np
    if MIN_WORDS > MAX_WORDS:
        raise ValueError("MIN_WORDS must be <= MAX_WORDS")
    # pick total length (inclusive)
    L = int(np.random.randint(MIN_WORDS, MAX_WORDS + 1))
    half = L // 2
    left = list(np.random.choice(WORDS_POOL, size=half, replace=True))
    if L % 2 == 1:
        middle = np.random.choice(WORDS_POOL)
        words = left + [middle] + left[::-1]
    else:
        words = left + left[::-1]
    return " ".join(words)

def export_function_specs(f_list, file_path):
    """
    Export specifications of functions in f_list to a CSV file at file_path.
    CSV columns: Function Name, Number of Arguments, Defaults, Annotations, Is Lambda.
    Uses pandas to write the CSV.
    """
    import pandas as pd
    import inspect

    rows = []
    for f in f_list:
        if not callable(f):
            continue
        try:
            sig = inspect.signature(f)
            params = sig.parameters
            num_args = len(params)
            defaults = {
                name: repr(p.default)
                for name, p in params.items()
                if p.default is not inspect._empty
            }
            annotations = {
                name: repr(p.annotation)
                for name, p in params.items()
                if p.annotation is not inspect._empty
            }
            if sig.return_annotation is not inspect._empty:
                annotations['return'] = repr(sig.return_annotation)
        except (ValueError, TypeError):
            # Could not get a signature (e.g., some builtins); fill with blanks
            num_args = None
            defaults = {}
            annotations = {}

        rows.append({
            'Function Name': getattr(f, '__name__', str(f)),
            'Number of Arguments': num_args,
            'Defaults': str(defaults) if defaults else '',
            'Annotations': str(annotations) if annotations else '',
            'Is Lambda': getattr(f, '__name__', '') == '<lambda>',
        })

    df = pd.DataFrame(rows, columns=[
        'Function Name', 'Number of Arguments', 'Defaults', 'Annotations', 'Is Lambda'
    ])
