def export_function_specs(f_list, file_path):
    """
    Exports specifications of functions in f_list to a CSV at file_path using pandas.
    CSV columns:
      - 'Function Name'
      - 'Number of Arguments'
      - 'Defaults'
      - 'Annotations'
      - 'Is Lambda'
    """
    import inspect
    import pandas as pd

    def fmt_default_map(sig):
        items = []
        for p in sig.parameters.values():
            if p.default is not inspect._empty:
                items.append(f"{p.name}={repr(p.default)}")
        return ", ".join(items)

    def fmt_annotations(sig):
        parts = []
        for p in sig.parameters.values():
            ann = p.annotation
            if ann is not inspect._empty:
                if isinstance(ann, type):
                    parts.append(f"{p.name}: {ann.__name__}")
                else:
                    parts.append(f"{p.name}: {repr(ann)}")
        ra = sig.return_annotation
        if ra is not inspect._empty:
            if isinstance(ra, type):
                parts.append(f"return: {ra.__name__}")
            else:
                parts.append(f"return: {repr(ra)}")
        return ", ".join(parts)

    rows = []
    for f in f_list:
        sig = inspect.signature(f)
        rows.append({
            "Function Name": getattr(f, "__name__", str(f)),
            "Number of Arguments": len(sig.parameters),
            "Defaults": fmt_default_map(sig),
            "Annotations": fmt_annotations(sig),
            "Is Lambda": (getattr(f, "__name__", "") == "<lambda>"),
        })

    df = pd.DataFrame(rows, columns=["Function Name", "Number of Arguments", "Defaults", "Annotations", "Is Lambda"])
    df.to_csv(file_path, index=False)

