    """
    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return a dictionary of the normalized data.

    Raises:
        requests.HTTPError on HTTP errors (e.g., user not found).
    """
    import requests, unicodedata

    def _norm_str(s):
        # Normalize Unicode (NFKD) then drop non-ASCII
        return unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode("ascii")

    def _normalize(value):
        if isinstance(value, str):
            return _norm_str(value)
        if isinstance(value, dict):
            return {(_norm_str(k) if isinstance(k, str) else k): _normalize(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_normalize(v) for v in value]
        if isinstance(value, tuple):
            return tuple(_normalize(v) for v in value)
        return value

    resp = requests.get(f"https://api.github.com/users/{username}")
    resp.raise_for_status()
    return _normalize(resp.json())

