def count_word_lengths_starting_with(data, letter, case_sensitive=False):
    """
    data: dict of lists with a 'Word' column, e.g. {'Word': ['apple', 'Banana', ...], ...}
    letter: single character to filter words that start with this letter
    case_sensitive: if False (default), matching is case-insensitive
    Returns: dict {word_length: count}
    """
    import pandas as pd

    df = pd.DataFrame(data)
    if not case_sensitive:
        mask = df['Word'].str.lower().str.startswith(letter.lower(), na=False)
    else:
        mask = df['Word'].str.startswith(letter, na=False)

    lengths = df.loc[mask, 'Word'].str.len()
    return lengths.value_counts().sort_index().to_dict()
