def count_pos_without_last(sentence):
    import nltk
    from collections import Counter

    tokens = sentence.split()           # simple tokenization
    tokens = tokens[:-1]                # drop the last word
    if not tokens:
        return {}

    try:
        tagged = nltk.pos_tag(tokens)
    except LookupError:
        nltk.download('averaged_perceptron_tagger', quiet=True)
        tagged = nltk.pos_tag(tokens)

    return dict(Counter(tag for _, tag in tagged))

