def mean_var(L):
    """
    Calculate mean and variance of all numeric elements in a nested list L using numpy.
    Returns a tuple (mean, variance). Non-numeric elements will raise a ValueError.
    """
    import numpy as np

    def _gen(x):
        for e in x:
            if isinstance(e, (list, tuple, np.ndarray)):
                yield from _gen(e)
            else:
                yield e

