def nested_mode(L):
    """
    Return the mode (most common element) of all elements in nested list L.
    If multiple modes exist, SciPy returns the smallest one by sort order.
    Raises ValueError if L is empty (no elements).
    """
    from scipy import stats

    def _flatten(x):
        for item in x:
            if isinstance(item, (list, tuple)):
                yield from _flatten(item)
            else:
                yield item

    vals = list(_flatten(L))
    if not vals:
        raise ValueError("empty input")
    res = stats.mode(vals, axis=None)
    return res.mode.item()
