def json_stats_to_csv(json_path, csv_path):
    """
    Read a JSON file containing a list of dictionaries, compute mean and median per key (numeric values only),
    and write results to a CSV with columns: key, mean, median.
    """
    import json
    import csv
    import numpy as np

    with open(json_path, 'r') as f:
        data = json.load(f)

    if not isinstance(data, list):
        raise ValueError("JSON must contain a list of dictionaries")

    values_by_key = {}
    for item in data:
        if not isinstance(item, dict):
            continue
        for k, v in item.items():
            try:
                num = float(v)
            except Exception:
                continue
            values_by_key.setdefault(k, []).append(num)

    with open(csv_path, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['key', 'mean', 'median'])
        for k in sorted(values_by_key):
            arr = values_by_key[k]
            if not arr:
                writer.writerow([k, '', ''])
            else:
                a = np.array(arr, dtype=float)
                writer.writerow([k, float(np.mean(a)), float(np.median(a))])

def analyze_publication_times(articles, tz_name='UTC'):
    """
    Analyze publication times of articles.

    - articles: list of dicts with keys 'published_time' and 'category'.
        'published_time' can be:
          - a datetime.datetime object (naive assumed UTC)
          - an ISO-8601 string (e.g. "2023-09-01T12:34:56", "2023-09-01T12:34:56Z",
            or "2023-09-01T12:34:56+02:00")
    - tz_name: target timezone name (pytz timezone string), default 'UTC'

    Returns a dict mapping category -> {'count', 'mean_hour', 'min_hour', 'max_hour'},
    where hours are integers 0-23 and mean_hour is a float.
    """
    from datetime import datetime
    import pytz

    # helper to parse various datetime inputs into an aware datetime in UTC
    def _to_aware_utc(ts):
        if isinstance(ts, datetime):
            dt = ts
        else:
            s = str(ts).strip()
            # accept trailing 'Z' as UTC
            if s.endswith('Z'):
                s = s[:-1] + '+00:00'
            try:
                dt = datetime.fromisoformat(s)
            except Exception:
                # fallback try common formats without timezone (assume naive)
                for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S",
                            "%Y-%m-%d"):
                    try:
                        dt = datetime.strptime(s, fmt)
                        break
                    except Exception:
                        dt = None
                if dt is None:
                    raise ValueError("Unrecognized datetime format: " + str(ts))
        # make timezone-aware: assume naive datetimes are UTC
        if dt.tzinfo is None:
            return pytz.UTC.localize(dt)
        else:
            # convert any aware datetime to UTC for normalization
            return dt.astimezone(pytz.UTC)

    target_tz = pytz.timezone(tz_name)
    groups = {}  # category -> list of hour ints

    for art in articles:
        try:
            pub = art['published_time']
            cat = art['category']
        except Exception:
            # skip malformed entries
            continue
        try:
            dt_utc = _to_aware_utc(pub)
        except Exception:
            # skip unparseable dates
            continue
        dt_local = dt_utc.astimezone(target_tz)
        hour = dt_local.hour
        groups.setdefault(cat, []).append(hour)

    # summarize
    result = {}
    for cat, hours in groups.items():
        if not hours:
            continue
        count = len(hours)
        mean_hour = sum(hours) / count
        result[cat] = {
            'count': count,
            'mean_hour': mean_hour,
            'min_hour': min(hours),
            'max_hour': max(hours),
        }
    return result

