def extract_and_plot_numbers(json_data, path, kind='hist', bins=30, title=None):
    """
    Extract numerical values from json_data following a path of keys and plot them with seaborn.
    - json_data: nested dict/list structure (parsed JSON)
    - path: list of keys (e.g. ['a','b','c']) or dot-separated string ("a.b.c")
    - kind: 'hist' (default), 'box', or 'violin'
    - bins: number of bins for histogram
    - title: optional plot title
    Returns the list of extracted numbers.
    """
