    import matplotlib.pyplot as plt
    import numbers

    # normalize path to list of keys
    if isinstance(path, str):
        keys = path.split('.') if path else []
    else:
        keys = list(path)

    nums = []

    def collect(obj, remaining_keys):
        if not remaining_keys:
            # terminal: gather numeric leaves (and traverse lists/dicts to find numbers)
            if isinstance(obj, dict):
                for v in obj.values():
                    collect(v, [])
            elif isinstance(obj, (list, tuple)):
                for item in obj:
                    collect(item, [])
            elif isinstance(obj, numbers.Number) and not isinstance(obj, bool):
                nums.append(obj)
            return

        k = remaining_keys[0]
        rest = remaining_keys[1:]
        # if current object is a list/tuple, traverse each element with same keys
        if isinstance(obj, (list, tuple)):
            for item in obj:
                collect(item, remaining_keys)
        elif isinstance(obj, dict):
            if k in obj:
                collect(obj[k], rest)
        # otherwise can't follow path

    collect(json_data, keys)

    if not nums:
        raise ValueError("No numeric values found at the specified path.")

    plt.figure()
    if kind == 'hist':
        sns.histplot(nums, bins=bins, kde=False)
    elif kind == 'box':
        sns.boxplot(x=nums)
    elif kind == 'violin':
        sns.violinplot(x=nums)
    else:
        raise ValueError("Unsupported kind: choose 'hist', 'box', or 'violin'")

