def plot_numbers_from_json(json_obj, path, kind='hist', bins=30, figsize=(8, 4), show=True):
    """
    Extract numerical values from a JSON-like structure and visualize them using seaborn.

    Parameters
    - json_obj: nested dict/list structure (parsed JSON)
    - path: list of keys OR dot-separated string, e.g. "data.items.value" or ["data", "items", "value"]
            use "*" to mean "all elements" when the current node is a list (e.g. "data.items.*.value")
            integer indices are accepted (as ints or numeric strings) to index lists
    - kind: 'hist' (histogram, default) or 'line' (line plot of extracted values in order)
    - bins: number of histogram bins
    - figsize: tuple passed to matplotlib.figure.Figure
    - show: whether to call plt.show()

    Returns: (values, ax) where values is a flat list of extracted numeric values and ax is the matplotlib Axes
    Raises ValueError if no numeric values are found.

    Example:
    plot_numbers_from_json(data, "records.*.score")
    """
    import seaborn as sns
    import matplotlib.pyplot as plt

    # Normalize path to list of keys
    if isinstance(path, str):
        keys = path.split('.')
    else:
        keys = list(path)

    def is_number(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def try_number(x):
        if is_number(x):
            return float(x)
        if isinstance(x, str):
            try:
                return float(x)
            except Exception:
                return None
        return None

    # recursive traversal returning list of numbers
    def traverse(node, remaining_keys):
        if not remaining_keys:
            # leaf: collect numeric values from node (single number or list of numbers)
            if is_number(node):
                return [float(node)]
            if isinstance(node, str):
                v = try_number(node)
                return [v] if v is not None else []
            if isinstance(node, list):
                out = []
                for it in node:
                    if is_number(it):
                        out.append(float(it))
                    else:
                        v = try_number(it)
                        if v is not None:
                            out.append(v)
                return out
            return []
        key = remaining_keys[0]

        # If current node is a list, either use wildcard '*' or apply key to every element
        if isinstance(node, list):
            out = []
            if key == '*' or key == slice(None):
                for item in node:
                    out.extend(traverse(item, remaining_keys[1:]))
                return out
            # if key is an int or numeric string, treat as index
            try:
                idx = int(key)
                if 0 <= idx < len(node):
                    return traverse(node[idx], remaining_keys[1:])
                else:
                    return []
            except Exception:
                # otherwise try applying key into every element (common case)
                for item in node:
                    out.extend(traverse(item, remaining_keys))
                return out

        # If current node is a dict, look up key
        if isinstance(node, dict):
            if key in node:
                return traverse(node[key], remaining_keys[1:])
            else:
                return []
        # otherwise nothing to traverse
        return []

    values = traverse(json_obj, keys)
    if not values:
        raise ValueError("No numeric values found for path: {}".format(path))

    # Plot using seaborn
    fig, ax = plt.subplots(figsize=figsize)
    if kind == 'line':
        sns.lineplot(x=list(range(len(values))), y=values, marker='o', ax=ax)
        ax.set_xlabel('index')
        ax.set_ylabel('value')
    else:  # default histogram
        sns.histplot(values, bins=bins, kde=False, ax=ax)
        ax.set_xlabel('value')
        ax.set_ylabel('count')

    ax.set_title(f"Extracted {len(values)} numeric value(s) from path: {path}")
    if show:
        plt.show()

    return values, ax

