def process_and_plot_json(json_str, key=None, title='Normalized Data'):
    """
    Parse a JSON string to extract numerical data, Min-Max normalize them using sklearn,
    and generate a line plot (matplotlib).

    Args:
        json_str (str): JSON string containing numeric data. Examples accepted:
                        - "[1, 2, 3]"
                        - '[{"value": 1}, {"value": 2}]' (use key='value')
                        - '{"a":[1,2,3], "b": 4}'
        key (str, optional): If JSON is a list of dicts, extract numbers using this key.
        title (str, optional): Plot title.

    Returns:
        list of float: Normalized values in the range [0, 1].
    """
    import json
    import numpy as np
    import matplotlib.pyplot as plt
    from sklearn.preprocessing import MinMaxScaler

    data = json.loads(json_str)
    nums = []

    # If it's a list
    if isinstance(data, list):
        # list of simple numbers
        if all(isinstance(x, (int, float)) for x in data):
            nums = [float(x) for x in data]
        # list of dicts and a key provided
        elif all(isinstance(x, dict) for x in data) and key is not None:
            for obj in data:
                v = obj.get(key)
                if isinstance(v, (int, float)):
                    nums.append(float(v))
        else:
            # try to collect numeric values from various possible list element types
            for item in data:
                if isinstance(item, (int, float)):
                    nums.append(float(item))
                elif isinstance(item, dict):
                    for v in item.values():
                        if isinstance(v, (int, float)):
                            nums.append(float(v))
                elif isinstance(item, list):
                    for v in item:
                        if isinstance(v, (int, float)):
                            nums.append(float(v))

    # If it's a dict
    elif isinstance(data, dict):
        if key and key in data:
            vals = data[key]
            if isinstance(vals, list):
                for v in vals:
                    if isinstance(v, (int, float)):
                        nums.append(float(v))
            elif isinstance(vals, (int, float)):
                nums = [float(vals)]
        else:
            for v in data.values():
                if isinstance(v, (int, float)):
                    nums.append(float(v))
                elif isinstance(v, list):
                    for x in v:
                        if isinstance(x, (int, float)):
                            nums.append(float(x))

    if not nums:
        raise ValueError("No numeric data found in the provided JSON string.")

    arr = np.array(nums).reshape(-1, 1)
    scaler = MinMaxScaler()
    normalized = scaler.fit_transform(arr).flatten()

    plt.figure()
    plt.plot(normalized, marker='o')
    plt.title(title)
    plt.xlabel('Index')
    plt.ylabel('Normalized value (0-1)')
    plt.grid(True)
    plt.tight_layout()
    plt.show()

    return normalized.tolist()
