def extract_dicts_from_url(url, timeout=10):
    """
    Fetch a webpage, parse <script> tags with BeautifulSoup, and attempt to evaluate
    any {...} / [...] substrings found in those scripts as Python dictionaries.
    Returns a list of dicts that were successfully parsed.
    Requires: requests, bs4 (BeautifulSoup)
    """
    import requests
    from bs4 import BeautifulSoup
    import json
    import ast
    import re

    def _extract_brace_substrings(s):
        # Return balanced {...} or [...] substrings (simple stack-based extractor).
        res = []
        stack = []
        start = None
        for i, ch in enumerate(s):
            if ch in '{[':
                if not stack:
                    start = i
                stack.append(ch)
            elif ch in '}]':
                if not stack:
                    continue
                opening = stack.pop()
                # basic matching check
                if (opening == '{' and ch != '}') or (opening == '[' and ch != ']'):
                    # mismatch: reset
                    stack = []
                    start = None
                    continue
                if not stack and start is not None:
                    res.append(s[start:i+1])
                    start = None
        return res

    try:
        resp = requests.get(url, timeout=timeout)
        resp.raise_for_status()
        html = resp.text
    except Exception:
        return []

    soup = BeautifulSoup(html, "html.parser")
    found = []

    for script in soup.find_all("script"):
        text = script.string
        if text is None:
            text = script.get_text("")  # fallback
        if not text:
            continue

        for candidate in _extract_brace_substrings(text):
            cand = candidate.strip()
            # Try json.loads first (works when it's valid JSON)
            try:
                obj = json.loads(cand)
                if isinstance(obj, dict):
                    found.append(obj)
                    continue
                # if it's a list, maybe contains dicts; collect those
                if isinstance(obj, list):
                    for item in obj:
                        if isinstance(item, dict):
                            found.append(item)
                    continue
            except Exception:
                pass

            # Fallback: try to convert JS-like literals to Python and ast.literal_eval
            s = re.sub(r'\bnull\b', 'None', cand, flags=re.IGNORECASE)
            s = re.sub(r'\btrue\b', 'True', s, flags=re.IGNORECASE)
            s = re.sub(r'\bfalse\b', 'False', s, flags=re.IGNORECASE)
            try:
                obj = ast.literal_eval(s)
                if isinstance(obj, dict):
                    found.append(obj)
                elif isinstance(obj, list):
                    for item in obj:
                        if isinstance(item, dict):
                            found.append(item)
            except Exception:
                # give up on this candidate
                pass

    return found

def geolocate_domains_from_text(text):
    """
    Extract all URLs from the provided text, extract the domain for each URL,
    and query ip-api.com for geolocation data for each domain.

    Returns a dict mapping domain -> geolocation JSON (or an error dict).
    """
    import re
    from urllib.parse import urlparse
    import requests

    # find typical URLs (http(s) and www.)
    urls = re.findall(r'\b(?:https?://|www\.)\S+\b', text)

    # clean trailing punctuation and ensure a scheme for parsing
    cleaned = []
    for u in urls:
        u = u.rstrip('.,;:!?)"\']')
        if not u:
            continue
        if not u.startswith(('http://', 'https://')):
            u = 'http://' + u
        cleaned.append(u)

    # extract domains
    domains = set()
    for u in cleaned:
        netloc = urlparse(u).netloc
        if '@' in netloc:  # strip possible userinfo
            netloc = netloc.split('@')[-1]
        netloc = netloc.split(':')[0]  # strip port if present
        if netloc:
            domains.add(netloc)

    # query ip-api.com for each domain
    results = {}
    for d in sorted(domains):
        try:
            resp = requests.get(f'http://ip-api.com/json/{d}', timeout=5)
            if resp.status_code == 200:
                results[d] = resp.json()
            else:
                results[d] = {'error': f'HTTP {resp.status_code}'}
        except Exception as e:
            results[d] = {'error': str(e)}

    return results

