import re
import requests
from bs4 import BeautifulSoup

def extract_title_from_text(text):
    """
    Extract the first URL found in `text`, fetch that page, and return its <title> text.
    If no URL is found or the fetch/title retrieval fails, returns an error message string.
    """
    # find a simple http/https or www URL
    m = re.search(r'(https?://[^\s<>"]+|www\.[^\s<>"]+)', text)
    if not m:
        return "No valid URL found in the input."
    url = m.group(0)
    if url.startswith("www."):
        url = "http://" + url

    try:
        resp = requests.get(url, timeout=10, headers={"User-Agent": "python-requests"})
    except requests.RequestException as e:
        return f"Error fetching URL: {e}"

    if resp.status_code != 200:
        return f"Failed to fetch URL: HTTP {resp.status_code}"

    soup = BeautifulSoup(resp.text, "html.parser")
    if soup.title and soup.title.string:
        return soup.title.string.strip()
    return "No title found at the URL."

def extract_and_get_title(text):
    """
    Extract the first http/https URL from `text` and return the web page's <title> text.
    Returns an error message string if no URL is found or the fetch/parsing fails.
    """
    import re
    import requests
    from bs4 import BeautifulSoup

    m = re.search(r'(https?://[^\s<>"]+)', text)
    if not m:
        return "Error: No valid URL found in input."

    url = m.group(1).rstrip('.,)')  # strip common trailing punctuation

    try:
        resp = requests.get(url, timeout=10, headers={"User-Agent": "Mozilla/5.0"})
    except requests.RequestException as e:
        return f"Error fetching URL: {e}"

    if resp.status_code != 200:
        return f"Error fetching URL: status code {resp.status_code}"

    try:
        soup = BeautifulSoup(resp.content, "html.parser")
        title_tag = soup.title
        if title_tag and title_tag.string:
            return title_tag.string.strip()
        else:
            return "Error: No title found on the page."
    except Exception as e:
        return f"Error parsing HTML: {e}"

