def post_first_url(myString, api_endpoint, token):
    """
    Extract the first URL from myString and POST it as JSON to api_endpoint using the given auth token.
    Returns the response JSON if possible, otherwise the response text.
    Raises ValueError if no URL is found, and raises requests.HTTPError for bad HTTP responses.
    """
    import re, requests

    m = re.search(r'https?://\S+', myString)
    if not m:
        raise ValueError("No URL found in input string")

    # trim common trailing punctuation
    url = m.group(0).rstrip('.,;:!?)"\']')

    headers = {
        'Authorization': f'Bearer {token}',
        'Content-Type': 'application/json',
    }
    payload = {'url': url}

    resp = requests.post(api_endpoint, json=payload, headers=headers)
    resp.raise_for_status()
    try:
        return resp.json()
    except ValueError:
        return resp.text

